/* AURELIA category catalogue normalization: exactly 100 distinct retail products per collection. */
(()=>{const defs={
"Earrings":["Pearl","Crystal","Floral","Hoop","Drop","Stud","Charm","Layered","Satin","Gold-Tone"],
"Necklaces":["Layered","Pendant","Pearl","Charm","Crystal","Lariat","Chain","Heart","Floral","Statement"],
"Rings":["Stackable","Crystal","Pearl","Heart","Floral","Twist","Minimal","Signet","Halo","Adjustable"],
"Bracelets & Bangles":["Cuff","Chain","Pearl","Charm","Crystal","Bangle","Twist","Heart","Layered","Open"],
"Hair Accessories":["Crystal Hair Clip","Pearl Headband","Satin Scrunchie","Bow Clip","Floral Hair Pin","Velvet Claw Clip","Rhinestone Barrette","Silk Scarf Tie","Pearl Hair Comb","Statement Headband"],
"Bags & Clutches":["Satin Clutch","Embroidered Potli","Pearl Mini Bag","Chain Shoulder Bag","Quilted Crossbody","Crystal Evening Bag","Bow Clutch","Velvet Potli","Metallic Wristlet","Beaded Box Clutch"],
"Festive & Bridal":["Bridal Jhumka","Maang Tikka","Kundan Choker","Polki Set","Bridal Hair Pin","Wedding Bracelet","Festive Choker","Crystal Jhumka","Pearl Bridal Set","Temple Pendant"],
"Fashion Accessories":["Oversized Sunglasses","Silk Belt","Fashion Brooch","Statement Belt","Classic Sunglasses","Charm Keyring","Decorative Hair Ribbon","Waist Chain","Fashion Pin","Mini Scarf"],
"Anklets & Payals":["Pearl Payal","Charm Anklet","Silver-Tone Payal","Crystal Anklet","Beaded Payal","Layered Anklet","Minimal Anklet","Floral Payal","Bell Charm Payal","Chain Anklet"],
"Brooches & Pins":["Crystal Brooch","Pearl Brooch","Floral Pin","Bow Pin","Vintage Brooch","Rhinestone Pin","Charm Brooch","Statement Pin","Leaf Brooch","Elegant Lapel Pin"],
"Scarves & Stoles":["Satin Scarf","Printed Stole","Silk-Feel Scarf","Embroidered Stole","Floral Scarf","Chiffon Stole","Pearl-Edge Scarf","Festive Stole","Soft Wrap Scarf","Printed Hair Scarf"],
"Travel & Vanity":["Jewellery Travel Case","Vanity Pouch","Cosmetic Bag","Makeup Organiser","Jewellery Roll","Travel Mirror","Accessory Pouch","Compact Vanity Case","Beauty Travel Kit","Jewellery Box"]};
const cats=Object.keys(defs);
const seedCount=Object.fromEntries(cats.map(cat=>[cat,CATALOG_PRODUCTS.filter(p=>p.cat===cat).length]));
const generated=CATALOG_PRODUCTS.filter(p=>p.id>12);
let cursor=0;
cats.forEach(cat=>{const need=Math.max(0,100-seedCount[cat]);for(let n=1;n<=need;n++){const p=generated[cursor++];if(!p)break;p.cat=cat;const base=defs[cat][(n-1)%defs[cat].length];p.name=base+" "+String(n).padStart(2,"0");p.desc="AURELIA "+cat.toLowerCase()+" designed for effortless personal style, gifting and everyday wear.";}});})();
